const people = ['Alex', 'Blair', 'Casey'];
const itemsElement = document.querySelector('#items');
const tipInput = document.querySelector('#tip');
const itemCount = document.querySelector('#item-count');
const totalsElement = document.querySelector('#people');
const grandTotalElement = document.querySelector('#grand-total');
const money = cents => `$${(cents / 100).toFixed(2)}`;

function updateTotals() {
  const owed = people.map(() => 0);
  let count = 0;

  for (const row of itemsElement.querySelectorAll('.item-row')) {
    count++;
    const price = Math.max(0, Math.round((Number(row.querySelector('[data-price]').value) || 0) * 100));
    const selected = [...row.querySelectorAll('[data-person]:checked')].map(input => Number(input.dataset.person));
    if (selected.length) {
      const base = Math.floor(price / selected.length);
      let remainder = price - base * selected.length;
      for (const index of selected) owed[index] += base + (remainder-- > 0 ? 1 : 0);
    }
  }

  const tip = Math.max(0, Number(tipInput.value) || 0);
  const tipped = owed.map(cents => Math.round(cents * (1 + tip / 100)));
  totalsElement.replaceChildren(...people.map((name, index) => {
    const card = document.createElement('div');
    card.className = 'person-total';
    const label = document.createElement('span');
    label.textContent = name;
    const amount = document.createElement('strong');
    amount.textContent = money(tipped[index]);
    card.append(label, amount);
    return card;
  }));
  grandTotalElement.textContent = money(tipped.reduce((sum, amount) => sum + amount, 0));
  itemCount.textContent = `${count} ${count === 1 ? 'item' : 'items'}`;
}

function addItem() {
  const row = document.createElement('div');
  row.className = 'item-row';
  const name = document.createElement('input');
  name.type = 'text';
  name.placeholder = 'Item name';
  name.setAttribute('aria-label', 'Item name');
  const price = document.createElement('input');
  price.type = 'number';
  price.min = '0';
  price.step = '0.01';
  price.placeholder = '0.00';
  price.inputMode = 'decimal';
  price.dataset.price = '';
  price.setAttribute('aria-label', 'Item price in dollars');
  const checks = document.createElement('div');
  checks.className = 'checks';
  checks.setAttribute('role', 'group');
  checks.setAttribute('aria-label', 'People sharing this item');

  people.forEach((person, index) => {
    const label = document.createElement('label');
    label.className = 'person-check';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.dataset.person = String(index);
    checkbox.setAttribute('aria-label', `${person} shares item`);
    const text = document.createElement('span');
    text.textContent = person;
    label.append(checkbox, text);
    checks.append(label);
  });

  const remove = document.createElement('button');
  remove.type = 'button';
  remove.className = 'remove';
  remove.textContent = '×';
  remove.setAttribute('aria-label', 'Remove item');
  row.append(name, price, checks, remove);
  itemsElement.append(row);
  name.focus();
}

document.querySelector('#add-item').addEventListener('click', addItem);
tipInput.addEventListener('input', updateTotals);
itemsElement.addEventListener('input', updateTotals);
itemsElement.addEventListener('change', updateTotals);
itemsElement.addEventListener('click', event => {
  const button = event.target.closest('.remove');
  if (button) {
    const row = button.closest('.item-row');
    const nextFocus = row.nextElementSibling?.querySelector('input') || row.previousElementSibling?.querySelector('input') || document.querySelector('#add-item');
    row.remove();
    updateTotals();
    nextFocus.focus();
  }
});
document.querySelector('#add-item').addEventListener('click', updateTotals);
updateTotals();
